/**
 * SERVICE LETTER HTML TEMPLATE
 * Page: 595 × 842 px (Figma exact — PDF points A4)
 * All coordinates taken directly from Figma spec.
 */

const esc = (str) =>
  String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const formatDate = (value) => {
  if (!value) return '';
  const d = new Date(value);
  if (isNaN(d.getTime())) return value;
  return `${String(d.getDate()).padStart(2,'0')}.${String(d.getMonth()+1).padStart(2,'0')}.${d.getFullYear()}`;
};

const LOGO_B64 = '';
const WATERMARK_B64 = '';


const PAI_TEXT_B64 = '';
const generateServiceLetterHTML = (data) => {
  const employeeName = data.employeeName || 'Name';
  const designation  = data.position    || 'Designation';
  const role         = data.department  || 'Role';
  const letterDate   = formatDate(data.letterDate) || 'DD.MM.YYYY';
  const startDate    = formatDate(data.joiningDate) || 'Start Date';
  const endDate      = formatDate(data.endDate)     || 'End Date';
  const generatedBy  = data.generatedBy || 'Thileksana Suntharamouleegan';

  const responsibilities = String(data.responsibilities || '')
    .split('\n').map(r => r.trim()).filter(Boolean);

  const responsibilitiesHtml = responsibilities.length
    ? responsibilities.map((r, i) => `<div>${i + 1}. ${esc(r)}</div>`).join('')
    : `<div>1. Developed and maintained web and mobile applications.</div>
       <div>2. Collaborated with cross-functional teams on project deliverables.</div>`;

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<title>Service Letter</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box;}
  @page{size:595px 842px;margin:0;}
  html,body{
    width:595px;height:842px;
    font-family:"Times New Roman",serif;
    -webkit-print-color-adjust:exact;
    print-color-adjust:exact;
    background:#fff;
    }

  /* PAGE */
  .page{
    position:relative;
    width:595px;height:842px;
    overflow:hidden;
    background:#fff;
  }

/* PAGE BORDER OVERLAY — does not offset child elements */
.page::after{
  content:'';
  position:absolute;
  inset:0;
  border:1px solid #000000;
  pointer-events:none;
  z-index:9999;
}

  /* HEADER LOGO — Figma: w100 h100 top5 left24 */
  .hdr-logo{
    position:absolute;
    top:5px;left:24px;
    width:100px;height:100px;
    object-fit:contain;
     
  }

  /* BRAND NAME — Figma: w77 h19 top95 left39 font:Archivo Narrow 700 14px #88BD47 */
  .hdr-brand{
    position:absolute;
    top:95px;left:39px;
    width:77px;height:19px;
    color:#88BD47;
    font-family:'Archivo Narrow',Arial Narrow,sans-serif;
    font-size:14px;font-weight:700;
    letter-spacing:0;line-height:1;
    white-space:nowrap;
    margin-top:12px; 
  }

  /* GRADIENT LINE — Figma: w424 top56 left172 border3px */
  .hdr-line{
    position:absolute;
    top:56px;left:172px;
    right:0;height:3px;
    background:linear-gradient(90deg,#26A1B3 0%,#75C676 100%);
  }

  /* WATERMARK — Figma: w500 h500 top171 left48 opacity0.2 */
  .watermark{
    position:absolute;
    top:171px;left:48px;
    width:500px;height:500px;
    object-fit:contain;
    opacity:0.2;
    pointer-events:none;
  }

  
/* PINEAPPLEAI TEXT WATERMARK — Figma: w548 h111 top604 left39 opacity0.2 */
.brand-text-wm{
  position:absolute;
  top:604px;left:39px;
  width:548px;height:111px;
  object-fit:contain;
  opacity:0.2;
  pointer-events:none;
  z-index:0;
}
  .content{
    position:absolute;
    top:130px;left:39px;right:38px;bottom:72px;
    color:#111;
    font-family:'Times New Roman',serif;
    font-size:12px;
    font-weight:400;
    line-height:1.4;
    letter-spacing:0;
    z-index:1;
  }
  /* Title — left 40px */
  .title{font-size:12px;font-weight:bold;margin-left:1px;margin-bottom:14px;}
  /* Date — left 39px */
  .date{margin-left:0;margin-bottom:16px;}
  /* Paragraphs — left 62px (39+23) */
  .paragraph{margin-left:0;margin-bottom:6px;text-align:justify;}
  .list{margin-left:23px;margin-bottom:14px;}
  .list div{margin-bottom:2px;text-align:justify;}
  .signature{margin-top:18px;margin-left:1px;}
  .signature-name{margin-top:12px;line-height:1.5;}
  .email{color:#0a58ca;text-decoration:underline;}
  strong{font-weight:bold;}

  /* FOOTER GRADIENT BAR — Figma: w595 h41 top801 */
  .footer-bar{
    position:absolute;
    top:801px;left:0;
    width:595px;height:41px;
    background:linear-gradient(90deg,#1EA69A 0%,#6DCE63 100%);
    z-index:1;
  }

  /* FOOTER WHITE CARD — Figma: w372 h49 top775 border-bottom-right-radius30 */
  .footer-card{
    position:absolute;
    top:775px;left:0;
    width:372px;height:49px;
    background:#fff;
    border-bottom-right-radius:30px;
    z-index:2;
  }

  /* FOOTER CONTACTS */
  .fc{
    position:absolute;
    color:#3D8656;
    font-family:"Times New Roman",serif;
    font-size:12px;line-height:1;
    z-index:3;
    display:flex;align-items:center;gap:3px;
  }
</style>
</head>
<body>
<div class="page">

  <!-- HEADER -->
  <img class="hdr-logo" src="data:image/png;base64,${LOGO_B64}" alt="PineappleAI"/>
  <div class="hdr-brand">PINEAPPLEAI</div>
  <div class="hdr-line"></div>

  <!-- WATERMARK -->
  <img class="watermark" src="data:image/png;base64,${WATERMARK_B64}" alt=""/>

<!-- PINEAPPLEAI TEXT WATERMARK -->
<img class="brand-text-wm" src="data:image/png;base64,${PAI_TEXT_B64}" alt=""/>

  <!-- CONTENT -->
  <div class="content">
    <div class="title">Service Letter</div>
    <div class="date">[${esc(letterDate)}]</div>

    <div class="paragraph">Dear ${esc(employeeName)},</div>

    <div class="paragraph">
      This letter is to confirm that <strong>${esc(employeeName)}</strong> has successfully
      completed an internship at <strong>PineappleAI</strong> from ${esc(startDate)} to
      ${esc(endDate)} as a ${esc(designation)} ${esc(role)}.
    </div>

    <div class="paragraph">During their tenure, ${esc(employeeName)} was responsible for:</div>
    <div class="list">${responsibilitiesHtml}</div>

    <div class="paragraph">
      Throughout their tenure, ${esc(employeeName)} demonstrated strong technical expertise in
      frontend and backend development, problem-solving abilities, and a commitment to delivering
      high-quality mobile and web applications.
    </div>

    <div class="paragraph">
      Their ability to collaborate with cross-functional teams, optimize application performance,
      and implement best coding practices made them a valuable asset to our organization.
      We appreciate their contributions and wish them success in their future endeavors.
    </div>

    <div class="paragraph">
      Please feel free to contact us at <span>ceo@pineappleai.cloud</span>
    </div>

    <div class="paragraph">We wish ${esc(employeeName)} all the best in their future endeavors.</div>

    <div class="signature">Sincerely,</div>
    <div class="signature-name">
      ${esc(generatedBy)}<br/>
      Chief HR Operational Officer<br/>
      <span>ceo@pineappleai.cloud</span>
    </div>
  </div>

  <!-- FOOTER GRADIENT BAR -->
  <div class="footer-bar"></div>

  <!-- FOOTER WHITE CARD -->
  <div class="footer-card"></div>

  <!-- FOOTER CONTACTS — Figma exact positions -->
  <div class="fc" style="top:777px;left:63px;">
    <svg width="13" height="13" viewBox="0 0 16 16" fill="none">
      <path d="M8 9.5a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3z" fill="#3D8656"/>
      <path d="M8 1a7 7 0 1 0 4.95 11.95l-.7-.7A6 6 0 1 1 14 8v1a1 1 0 0 1-2 0V8a4 4 0 1 0-.93 2.59l.71.71A5.97 5.97 0 0 0 14 9a6 6 0 0 0-6-6z" fill="#3D8656"/>
    </svg>@aibest
  </div>

  <div class="fc" style="top:775px;left:233px;">
    <svg width="13" height="13" viewBox="0 0 16 16" fill="none">
      <path d="M2 4a1 1 0 0 1 1-1h10a1 1 0 0 1 1 1v.5L8 8.5 2 4.5V4zm0 1.5 5.5 3.75a1 1 0 0 0 1 0L14 5.5V12a1 1 0 0 1-1 1H3a1 1 0 0 1-1-1V5.5z" fill="#3D8656"/>
    </svg>ceo@pineappleai.cloud
  </div>

  <div class="fc" style="top:796px;left:63px;">
    <svg width="13" height="13" viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.5" stroke="#3D8656" stroke-width="1.2"/>
      <path d="M8 1.5C8 1.5 5.5 4 5.5 8s2.5 6.5 2.5 6.5M8 1.5C8 1.5 10.5 4 10.5 8s-2.5 6.5-2.5 6.5M1.5 8h13" stroke="#3D8656" stroke-width="1.2"/>
    </svg>www.pineappleai.cloud
  </div>

  <div class="fc" style="top:796px;left:233px;">
    <svg width="13" height="13" viewBox="0 0 16 16" fill="none">
      <path d="M3.654 1.328a.678.678 0 0 0-1.015-.063L1.605 2.3c-.483.484-.661 1.169-.45 1.77a17.6 17.6 0 0 0 4.168 6.608 17.6 17.6 0 0 0 6.608 4.168c.601.211 1.286.033 1.77-.45l1.034-1.034a.678.678 0 0 0-.063-1.015l-2.307-1.794a.678.678 0 0 0-.58-.122l-2.19.547a1.745 1.745 0 0 1-1.657-.459L5.482 8.062a1.745 1.745 0 0 1-.46-1.657l.548-2.19a.678.678 0 0 0-.122-.58L3.654 1.328z" fill="#3D8656"/>
    </svg>+94-778-800-205
  </div>

</div>
</body>
</html>`;
};

module.exports = { generateServiceLetterHTML, formatDate };
